let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const json = { "content-type": "application/json" };
const unchanged = [
  { id: input.fromId, balance: input.fromBalance, version: input.fromVersion },
  { id: input.toId, balance: input.toBalance, version: input.toVersion }
];

function emit(status, body, { accounts = unchanged, committed = false, messages = [], ordering = [], failures = [], retryability = false } = {}) {
  console.log(JSON.stringify({
    http: { status, headers: json, body },
    database: { accounts, transaction: { committed } },
    messages,
    ordering,
    failures,
    retryability
  }));
}

const seen = Array.isArray(input.processedKeys) ? input.processedKeys : [];
const prior = input.priorResult ?? input.previousResult;

if (input.replay === true || seen.includes(input.idempotencyKey)) {
  const body = prior ?? { transferId: input.transferId, fromBalance: input.fromBalance, toBalance: input.toBalance, fromVersion: input.fromVersion, toVersion: input.toVersion };
  emit(200, body, { ordering: ["idempotency-replay"] });
} else if (
  (input.expectedFromVersion !== undefined && input.expectedFromVersion !== input.fromVersion) ||
  (input.expectedToVersion !== undefined && input.expectedToVersion !== input.toVersion)
) {
  emit(409, { error: "version_conflict", transferId: input.transferId }, {
    ordering: ["version-check", "rollback"],
    failures: ["version_conflict"],
    retryability: true
  });
} else if (!Number.isFinite(input.amount) || input.amount <= 0) {
  emit(400, { error: "invalid_amount", transferId: input.transferId }, { ordering: ["validate"], failures: ["invalid_amount"] });
} else if (input.fromBalance < input.amount) {
  emit(422, { error: "insufficient_funds", transferId: input.transferId }, {
    ordering: ["balance-check", "rollback"],
    failures: ["insufficient_funds"]
  });
} else {
  const fromBalance = input.fromBalance - input.amount;
  const toBalance = input.toBalance + input.amount;
  const fromVersion = input.fromVersion + 1;
  const toVersion = input.toVersion + 1;
  emit(201, { transferId: input.transferId, fromBalance, toBalance, fromVersion, toVersion }, {
    accounts: [
      { id: input.fromId, balance: fromBalance, version: fromVersion },
      { id: input.toId, balance: toBalance, version: toVersion }
    ],
    committed: true,
    messages: [{ type: "transfer.completed", transferId: input.transferId, fromId: input.fromId, toId: input.toId, amount: input.amount }],
    ordering: ["debit", "credit", "commit", "publish"]
  });
}

